-- ================================================================
-- 快递驿站智汇系统 · 联调/演示种子数据（MySQL 8）
-- 目标库：kdyzgl_test（测试库）
--
--   ★★★ 仅用于测试库 kdyzgl_test，禁止对 kdyzgl / courier_station 执行 ★★★
--   courier_station 为现网快递系统（绝不可碰）；kdyzgl 为结构库（保持干净，不加测试数据）。
--
-- 定位：独立脚本，不走 Flyway，只对测试库执行；用于前端演示站直连真实后端时的可见数据。
-- 与既有产物的关系：
--   1. 不改 V1~V15 迁移脚本、不改 sql/schema/mysql/init.sql 快照（种子不入快照）；
--   2. 结构/枚举以 docs/db.md v2.1 与 db/migration/mysql/V1~V15 为准；
--   3. 数据形态参照 Mock 真源 hrm-demo/src/shared/mock/*（演示规格），规模已裁剪。
--
-- 幂等方式：先 DELETE 子表→父表，再 INSERT（本项目无物理外键，D6 逻辑外键）；
--   不使用 DROP / TRUNCATE（无结构性破坏），可重复执行。
-- 时间口径：单一锚点 @base = CURDATE()（执行当日 0 点）做相对运算。
--   为什么用 CURDATE() 而非写死日期：本脚本服务于「演示站直连真实后端」，
--   写死日期会让数日后执行的「今日/近 7 天/近 30 天」页面全空；单锚点保证同日可复现。
-- 密码：employee.password 为 BCrypt 散列（$2a$ cost=10，60 字符），对应统一演示口令；
--   脚本只写散列、不写明文（生成与校验方式见 docs/deploy.md「测试库与联调种子数据」）。
-- 不包含：结构变更（无 DDL）、真实凭据、真实业务数据、服务器 IP。
-- ================================================================

SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;   -- 允许无 WHERE 的整表 DELETE（本脚本为重置型种子）
SET @base := CURDATE();     -- 单一时间锚点（执行当日 0 点）

-- ==================== 0. 清理（子表→父表） ====================
-- 为什么：重置型种子须可重复执行；先删子表再删父表，逻辑引用不留悬空。
-- 不清理的表（其数据由后端 SyncConfigSeeder / 登录流程持有，避免与自动播种冲突）：
--   sync_config_item / sync_config_option / sync_config_global / sync_config_station_override、
--   sync_station_config（5 表由 SyncConfigSeeder 幂等播种，见 docs/deploy.md）、
--   auth_trusted_device（设备信任由登录流程写入，测试库无需预置）。
DELETE FROM `hr_flow_step`;
DELETE FROM `hr_flow`;
DELETE FROM `payroll_item`;
DELETE FROM `payroll`;
DELETE FROM `payroll_rule_item`;
DELETE FROM `payroll_rule`;
DELETE FROM `leave_log`;
DELETE FROM `leave_request`;
DELETE FROM `leave_setting`;
DELETE FROM `attendance_record`;
DELETE FROM `attendance_makeup`;
DELETE FROM `attendance_schedule`;
DELETE FROM `attendance_shift`;
DELETE FROM `attendance_rule`;
DELETE FROM `kpi_score`;
DELETE FROM `kpi_metric`;
DELETE FROM `hr_salary_log`;
DELETE FROM `hr_salary`;
DELETE FROM `hr_profile`;
DELETE FROM `work_order_timeline`;
DELETE FROM `work_order_transfer`;
DELETE FROM `work_order`;
DELETE FROM `work_order_dispatch_rule`;
DELETE FROM `notification`;
DELETE FROM `parcel`;
DELETE FROM `sync_task_log`;
DELETE FROM `sync_task`;
DELETE FROM `login_log`;
DELETE FROM `client_log`;
DELETE FROM `employee`;
DELETE FROM `station`;
DELETE FROM `department`;

-- ==================== 1. 组织：部门 + 驿站 ====================
-- 为什么播这些：看板的部门树/驿站选择器、员工归属、考勤/工单/包裹的驿站维度都依赖这两张表。


-- ==================== 2. 账号：员工（既有 56；补充 8 见 §2.1，共 64） ====================
-- 为什么播这些：三角色齐全（ADMIN / STATION_ADMIN / STAFF）；status=1 启用、pwd_changed=1 免首登强制改密，
-- 否则演示账号登不进去。STAFF/STATION_ADMIN 必有 station_id，ADMIN 可为空。手机号为演示占位号（非真实号码）。
-- id=56 置 status=0，覆盖「含禁用」筛选与看板口径。

-- ==================== 2.1 补充账号：标准化演示账号 + 驿站 8 补齐（新增 8，id 57–64） ====================
-- 为什么补这些：
--   1) 「易记标准化演示账号」每端/每身份各一个，便于口头讲解与快速演示：
--      boss(ADMIN) 唯一可登网页端/PC 端；manager(STATION_ADMIN,站1) 移动端管理视角，兼验 PC 端 1110 拦截；
--      staff(STAFF,站1) 员工端主用；staff2(STAFF,站2) 备用员工账号。
--   2) 驿站 8「开发区分站」此前无站长、无员工，补齐 st008_admin + 3 名 st008_staff*；
--      驿站本身 status=0（停用）保持不变，作为「停用驿站」演示样例。
-- 幂等：employee 已在本脚本第 0 节整表 DELETE，本块与上方 §2 同一轮执行，重跑结果一致（不会重复插入）。
-- 口令：复用与 §2 同源散列（对应公开约定 demo1234），脚本仍只写散列、不写明文。
-- 范围：仅 employee 行；新账号的考勤/排班/工资/人事档案等业务数据有意留空（见 docs/demo-accounts.md）。
-- 手机号：13900000057–13900000064 为文档约定占位号（非真实号码）；dept_id 指向 §1 已建部门（1 总公司 / 2 运营部）。

-- ==================== 3. 登录日志 / 前端运行日志（补充，支撑看板与排障页） ====================
-- 为什么播这些：登录日志支撑看板「今日登录/登录趋势」；运行日志是「系统设置-运行日志」页的可见数据。
-- IP 一律 127.0.0.1（回环占位，非真实服务器 IP）。


-- ==================== 4. 考勤：规则 / 班次 / 排班 / 打卡 / 补卡 ====================
-- 为什么播这些：考勤页与工资单「考勤推算」规则项的数据源。排班与打卡只投城东驿站（对齐 Mock），
-- 避免 8 站满量拖慢首屏；打卡含 NORMAL/LATE/EARLY_LEAVE/ABNORMAL 四态；补卡含待审/已批/已驳。

-- 班次：每天 2 班次（早 08:00–16:00 / 晚 16:00–24:00）；已按用户裁定「删除中班」（保留原 id，保证排班引用不悬空）

-- 排班：每天 2 班次口径。原引用中班（shift_id=2/5/8…）的行已改派到同驿站「晚班」
-- （依据方案 §7 middayBoundaryMinute=720：12:00 起始归晚班序位；保证无悬空 shift_id，假设 A1 成立）



-- ==================== 5. 请假：设置 / 申请 / 留痕 ====================
-- 为什么播这些：覆盖 6 态状态机（待初审/待终审/已通过/已驳回/已撤销/已撤回）；留痕支撑详情页时间线。

-- 请假单：显式指定 id（1–12），与 leave_log.leave_id（1–12）对齐；
-- 为什么显式：DELETE 不重置自增，隐式 id 会漂移（原错配根因：日志挂 1–12、单据漂到 13–24）


-- ==================== 6. KPI：指标配置 + 月度评分 ====================
-- 为什么播这些：6 项启用指标权重合计 100（30/20/15/15/10/10）+ 1 项停用；评分按「一员工一账期一行」落库，
-- metric_detail 存逐指标快照，保证改权重后历史结果不回改（可解释、可审计）。


-- ==================== 7. 人事：档案 / 定薪 / 调薪留痕 / 入职离职流程 ====================
-- 为什么播这些：人事档案与定薪页、工资单 FIXED 规则项取数、入职离职流程页；留痕含 operator_id/operator_name（V14 新列）。





-- ==================== 8. 财务：计薪规则 / 工资单 ====================
-- 为什么播这些：规则表驱动算薪（8 项覆盖 FIXED/ATTENDANCE/KPI/MANUAL 四类来源）；工资单覆盖六态
-- （本期按驿站分布 + 上期样本），明细子表逐项落库，支撑详情页与员工端。金额只存正数，增扣由 item_type 承载。
-- 计薪规则：显式指定 id（1=标准/启用、2=旧版/停用），与 payroll_rule_item.rule_id、payroll.rule_id、
-- payroll.rule_snapshot.ruleId 三处历史引用点对齐；为什么显式：DELETE 不重置自增，隐式 id 会漂移（原错配根因）




-- ==================== 9. 工单：主表 / 时间线 / 转单 / 派单规则 ====================
-- 为什么播这些：覆盖四态（待处理/处理中/已解决/已关闭）与超 SLA 样本；时间线替代 Mock 的 handle_log 内嵌 JSON；
-- 派单规则为企微群消息→工单类型/优先级（对齐 Mock 5 条）。




-- ==================== 10. 通知（系统联动 + 手工发布，类型 1-6） ====================
-- 为什么播这些：站内信一行一收件人；手工发布带发布人快照与范围；请假联动产生 5/6 类型。

-- ==================== 11. 同步运行态：任务 / 日志 ====================
-- 为什么播这些：8 驿站 × 近 7 天批次，覆盖四态与失败重试路径；日志为批次抽屉数据。
-- 说明：本脚本不播 sync_station_config / sync_config_* 五表——后端 SyncConfigSeeder 已幂等播种，避免冲突（见 docs/deploy.md）。


-- ==================== 12. 包裹（7 个启用驿站 × 30 = 210，状态 0-4） ====================
-- 为什么播这些：包裹列表/看板/驿站排行需要可见数据；规模刻意不灌 20 万（大表容量建模属算法域）。
-- 8 号驿站停用不投包裹；近 72h 内入库只生成待入库/在库待取，避免「今天入库却已取件」的时序矛盾。

